<script module lang="ts">
/**
 * A treemap of parts of a whole (`design/components/treemap.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/treemap.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  chartMarks,
  chartPosition,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  joinSlot,
  measureBox,
  readChartPosition,
  readingRest,
  readingView,
  treemapModel,
  treemapReadout,
  treemapSelection,
  watchEffect,
  type ChartMessages,
  type ChartTooltipConfig,
  type TreemapItem,
  type ValueFormat,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/charts/treemap.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'

export interface TreemapProps {
  /**
   * Formats each item's value on its label, in the tooltip and in the twin.
   */
  format?: ValueFormat
  /**
   * The parts. An item with children is a group; deeper items are summed into the second level.
   */
  items: readonly TreemapItem[]
  label: string
  loading?: boolean
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the read item's key, label, value and share, on Enter, Space or click.
   */
  onSelect?: (selection: { key: string; label: string; value: number; share: number }) => void
  size?: 'sm' | 'md' | 'lg'
  tooltip?: false | ChartTooltipConfig
}
</script>

<script lang="ts">
let {
  format,
  items,
  label: labelOwn,
  loading = false,
  locale,
  messages = (() => DEFAULT_CHART_MESSAGES)(),
  onSelect,
  size = 'md',
  tooltip = (() => ({}))(),
}: TreemapProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get select() {
    return onSelect !== undefined
  },
}
let box = $state(UNMEASURED)
let reading = $state(createReading({ count: 0, seriesStart: null }))
let position = $state(readingRest(null))
let twinOpen = $state(false)
let warningLog = $state(createWarningLog())
let frame = $state<HTMLElement | null>(null)
let plot = $state<HTMLElement | null>(null)
const input = $derived({
  items,
  format,
  label,
  locale,
  messages,
  tooltip,
  loading,
  selectable: listening.select,
  box,
})
const model = $derived(treemapModel(input))
const view = $derived(readingView(position, model.leaves.length))
const readout = $derived(treemapReadout(input, model, view))
const activate = $derived(() => {
  const selection = treemapSelection(input, model, reading.now())
  if (selection !== null) onSelect?.(selection)
})
const walk = $derived({ count: model.leaves.length })
const marks = $derived({ walk, input, model, readout: treemapReadout, selection: treemapSelection })
const onKey = $derived((event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate()
    return
  }
  reading.update(walk)
  if (reading.key(event.key)) event.preventDefault()
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box = plot === null ? box : measureBox(plot, box)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  reading.subscribe((now) => {
    position = now
  })
}
watchEffect(effect2)
const effect3 = () => {
  warningLog.log(model.warnings, (message) => devWarning(true, message))
}
watchEffect(effect3, { watch: () => model.warnings.join('\n') })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = !listening.select
    ? () => {}
    : agentMember({
        member: 'Treemap',
        element: () => frame,
        state: () => ({
          items: chartMarks(marks, reading),
          position: chartPosition(marks, reading),
          count: walk.count,
        }),
        actions: {
          read: { argument: 'number', run: (value) => readChartPosition(marks, value, reading) },
          choose: {
            argument: 'id',
            run: (value) => chooseChartMark(marks, value, reading, activate),
          },
        },
      })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<figure
    bind:this={frame}
    class={chartFrame.frame}
    data-size={size}
    data-state={model.state}
    data-position={view.active ? view.index : undefined}
    aria-label={label}
    data-member="treemap"
    ><div class={chartFrame.region}
      ><div class={chartFrame.yAxis}></div
      ><div bind:this={plot} class={chartFrame.plot}
        >{#if model.state === 'empty'
          }<div class={chartFrame.empty}><span>{messages.empty}</span></div
        >{:else
          }<div
            class={styles.surface}
            tabindex="0"
            role="img"
            aria-label={label}
            onkeydown={(event) => { onKey(event) }}
            onclick={() => { activate() }}
            onpointerleave={() => { reading.clear() }}
            onblur={() => { reading.clear() }}
            >{#if model.plot !== null
              }<svg
                class={styles.marks}
                data-reading={(view.active) ? '' : undefined}
                width={model.plot?.width}
                height={model.plot?.height}
                aria-hidden="true"
                focusable="false"
                ><g
                  >{#each model.plot?.tiles ?? [] as tile (tile.id)
                    }<rect
                      class={styles.tile}
                      style:--pm-chart-mark={tile.fill}
                      data-active={(view.index === tile.index) ? '' : undefined}
                      x={tile.paint.x}
                      y={tile.paint.y}
                      width={tile.paint.width}
                      height={tile.paint.height}
                      rx={model.plot?.radius}
                    ></rect
                  >{/each
                }</g
                ><g
                  >{#each model.plot?.tiles ?? [] as tile (tile.id)
                    }<rect
                      class={styles.hit}
                      x={tile.hit.x}
                      y={tile.hit.y}
                      width={tile.hit.width}
                      height={tile.hit.height}
                      onpointerenter={() => { reading.moveTo(tile.index) }}
                      onclick={() => { reading.moveTo(tile.index) }}
                    ></rect
                  >{/each
                }</g
              ></svg
              ><div class={styles.text} aria-hidden="true"
                >{#each model.plot?.tiles ?? [] as tile (tile.id)
                  }{#if tile.plate !== null
                    }<span
                      class={styles.plate}
                      style:--pm-chart-text-x={`${tile.plate?.x}px`}
                      style:--pm-chart-text-y={`${tile.plate?.y}px`}
                      style:--pm-chart-text-width={`${tile.plate?.width}px`}
                      ><span class={styles.plateLabel}>{tile.plate?.label}</span
                      ><span class={styles.plateValue}>{tile.plate?.value}</span
                    ></span
                  >{/if
                }{/each
              }</div
            >{/if
          }</div
        >{/if
        }{#if readout.tooltip !== null
          }<div
            class={chartTooltip.tooltip}
            style:--pm-chart-tip-x={`${readout.tooltip?.x}px`}
            style:--pm-chart-tip-y={`${readout.tooltip?.y}px`}
            data-indicator={readout.tooltip?.indicator}
            data-side={readout.tooltip?.side}
            aria-hidden="true"
            >{#if readout.tooltip?.header !== undefined
              }<p class={chartTooltip.header}>{readout.tooltip?.header}</p
            >{/if
            }<ul class={chartTooltip.rows}
              >{#each readout.tooltip?.rows ?? [] as row (row.key)
                }<li class={chartTooltip.row}
                  ><span class={chartTooltip.key} style:--pm-chart-key={row.paint}></span
                  ><span class={chartTooltip.value}>{row.value}</span
                  ><span class={chartTooltip.label}>{row.label}</span
                ></li
              >{/each
            }</ul
          ></div
        >{/if
      }</div
      ><div class={chartFrame.xAxis}></div
    ></div
    >{#if model.legend
      }{#if model.painted.length > 0
        }<ul class={chartLegend.legend} data-key-shape="rect"
          >{#each model.painted as entry (entry.key)
            }<li class={chartLegend.item}
              ><span
                class={chartLegend.swatch}
                style:--pm-chart-key={entry.paint}
                aria-hidden="true"
              ></span
              >{#if entry.icon !== undefined
                }<span class={chartLegend.glyph}><Icon name={entry.icon} size="sm" /></span
              >{/if
              }<span class={chartLegend.label}>{entry.label}</span
            ></li
          >{/each
        }</ul
      >{/if
    }{/if
    }<span class={a11y.visuallyHidden}>{model.summary}</span
    ><div class={chartTwin.twin} data-state={twinOpen ? 'open' : 'closed'}
      ><div class={chartTwin.toggle}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          iconOnly={true}
          label={twinOpen ? messages.hideTable(label) : messages.showTable(label)}
          onClick={() => { twinOpen = !twinOpen }}
      /></div
      >{#if twinOpen
        }<div class={chartTwin.table}
          ><Table label={messages.tableLabel(label)} caption={messages.tableLabel(label)}
            ><TableHead
              ><TableRow
                >{#each model.twin.columns as column (column.key)
                  }<TableHeader numeric={column.numeric}>{column.label}</TableHeader
                >{/each
              }</TableRow
            ></TableHead
            ><TableBody
              >{#each model.twin.rows as row, line (line)
                }<TableRow
                  >{#each row as cell, cellIndex (model.twin.columns[cellIndex]?.key ?? cellIndex)
                    }<TableCell numeric={model.twin.columns[cellIndex]?.numeric}
                      >{cell === '' ? '—' : cell
                    }</TableCell
                  >{/each
                }</TableRow
              >{/each
            }</TableBody
          ></Table
        ></div
      >{/if
    }</div
    ><span class={a11y.visuallyHidden}
      ><div aria-live="polite" aria-atomic="true">{readout.announcement}</div
    ></span
  ></figure
>{/if
}{@render joined.end?.()}
